(function() {
    var params = new URLSearchParams(window.location.search);
    if (params.get('subscribed') !== '1') return;
    var toast = document.createElement('div');
    toast.style.cssText = 'position:fixed;left:20px;right:20px;bottom:20px;z-index:4000;max-width:760px;margin:0 auto;background:#0f4a50;color:#fff;border-radius:14px;padding:14px 46px 14px 16px;box-shadow:0 10px 30px rgba(0,0,0,.25);text-align:right;line-height:1.6;';
    toast.innerHTML = '<button type="button" aria-label="סגור הודעה" style="position:absolute;top:10px;left:10px;width:28px;height:28px;border:none;border-radius:50%;background:rgba(255,255,255,0.16);color:#fff;cursor:pointer;font-size:18px;line-height:1;">×</button><div style="font-size:15px;font-weight:700;">נרשמת בהצלחה! תודה שהצטרפת לקהילת "מתי טסים" ✈️</div>';
    document.body.appendChild(toast);
    function closeToast() { if (toast.parentNode) toast.parentNode.removeChild(toast); }
    toast.querySelector('button').addEventListener('click', closeToast);
    setTimeout(closeToast, 6000);
    if (window.history && window.history.replaceState) {
      var cleanUrl = window.location.origin + window.location.pathname + window.location.hash;
      window.history.replaceState({}, document.title, cleanUrl);
    }
  })();
